//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_HighScore::Update( float dt )
{
	if( !m_isInitialized )
		return;

	IMenu::Update( dt );
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_HighScore::LoseFocus()
{
	IMenu::LoseFocus();
}

//---------------------------------------------------------------------------------------------------------
// Perform Visual control actions
//---------------------------------------------------------------------------------------------------------
void Menu_HighScore::VisualControlDoAction( IVisualControl* visual_control, int action_id )
{
	switch ( action_id ) 
	{

	case action_back:
		{
			Transition_Start( transition_hide, action_back_trans );
		}
		break;
	case action_back_trans:
		{
			GetParent()->SubMenu_Change( "Menu_HighScoresLevelList" );
		}
		break;
	}
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_HighScore::SetLevel (int level)
{
	m_endless = false;
	m_level = level;

	CUserProfile profile = __PROFILE();
	GetCampaignScore(profile, &m_campaignScore, level);
}

void Menu_HighScore::SetEndless ()
{
	m_endless = true;

	CUserProfile profile = __PROFILE();
	GetEndlessScore(profile, &m_endlessScore);
}
